column19:
SELECT trading_date, interest_rate
FROM qlrr_interbank_rate
WHERE trading_date = :input_date;

SELECT AVG(interest_rate) AS avg_ir_N
FROM (
SELECT interest_rate FROM qlrr_interbank_rate
WHERE trading_date <= :input_date
ORDER BY trading_date DESC LIMIT :N
) t;

SELECT STDDEV_SAMP(interest_rate) AS sigma_ir
FROM qlrr_interbank_rate
WHERE trading_date <= :input_date;

SELECT TradingDate FROM IDXInfor
WHERE IndexCode = 'VNINDEX'
AND TradingDate = :input_date;

